"""Deliver an inspectable photographic manifest; original image files remain unchanged."""
import json
import shutil
from pathlib import Path

repo=Path(__file__).resolve().parents[1]
out=repo.parent/'outputs'
assets=out/'Smart-Capture-V3-reference-assets'
assets.mkdir(parents=True,exist_ok=True)
catalog=json.loads((repo/'shared/catalog.v3.json').read_text())
for a in catalog['assets'].values():
    shutil.copy2(repo/'shared'/a['path'],assets/Path(a['path']).name)
shutil.copy2(repo/'shared/catalog.v3.json',out/'Smart-Capture-V3-reference-manifest.json')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart Capture V3 · Photographic guide catalog</title><style>
*{box-sizing:border-box}body{margin:0;background:#0b0d11;color:#f7f8fa;font:15px system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:32px 24px}h1{font-size:clamp(28px,4vw,44px);letter-spacing:-1.5px;margin:8px 0}p{color:#b9c0ca;line-height:1.6;max-width:850px}.eyebrow{color:#dce9b5;font-size:12px;letter-spacing:2px;font-weight:700}.tools{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0;position:sticky;top:0;padding:12px 0;background:#0b0d11;z-index:1}select,input,button{font:inherit;color:inherit;background:#1b1e24;border:1px solid #454a53;border-radius:12px;min-height:48px;padding:12px}input{flex:1;min-width:180px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}article{border:1px solid #30353d;border-radius:18px;overflow:hidden;background:#15181e}article button{border:0;border-radius:0;width:100%;padding:0;display:block;background:#080a0d;cursor:zoom-in}svg{width:100%;height:220px;display:block}article .info{padding:18px}h2{font-size:17px;margin:0 0 8px}.code{font:11px ui-monospace,monospace;color:#dce9b5;overflow-wrap:anywhere}small{display:block;color:#aeb6c3;font-size:11px;line-height:1.5;margin-top:8px}dialog{border:1px solid #555b65;border-radius:20px;background:#11151b;color:white;width:min(1000px,94vw);padding:20px}dialog::backdrop{background:#000c}dialog svg{height:min(70vh,650px)}.complete{color:#dce9b5}footer{margin:30px 0;color:#aeb6c3;font-size:12px}</style><main>
<div class="eyebrow">SMART CAPTURE · NATIVE V3</div><h1>A photograph for every angle.</h1><p>34 shot types · 13 original photographic atlases · 272 checked body/shot crops. Select a body style to inspect its complete reference pack. These are original generated composition examples; interiors and fitted equipment vary. No primitive fallback is counted complete.</p>
<div class="tools"><label>Body style <select id="body"></select></label><label>Category <select id="category"><option value="">All</option><option>exterior</option><option>exterior_detail</option><option>interior</option><option>additional</option></select></label><input id="search" aria-label="Find a shot" placeholder="Find a shot, e.g. cockpit or engine"></div><p id="count"></p><section class="grid" id="grid"></section><footer>Images: image_gen.imagegen, text-to-image. Exact prompts, source provenance, usage terms, dimensions, hashes, anchors and crops are in the adjacent machine-readable manifest and source repository. A “complete” entry means a photographic crop exists and was inspected; it does not establish exact make/model shape, live CV accuracy or physical-device validation.</footer></main><dialog id="detail"><button id="close">Close</button><div id="large"></div></dialog><script>
const catalog=CATALOG;
const body=document.querySelector('#body'),grid=document.querySelector('#grid'),category=document.querySelector('#category'),search=document.querySelector('#search');
Object.keys(catalog.shots[0].references).forEach(b=>{const o=document.createElement('option');o.value=b;o.textContent=b==='truck'?'Pickup':b.charAt(0).toUpperCase()+b.slice(1);body.append(o)});
function svg(shot){const r=shot.references[body.value],a=catalog.assets[r.asset],[x,y,w,h]=r.rect;return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${shot.name}" viewBox="${x} ${y} ${w} ${h}"><g ${r.mirror?`transform="translate(${2*x+w} 0) scale(-1 1)"`:''}><image href="Smart-Capture-V3-reference-assets/${r.asset}" width="${a.width}" height="${a.height}"/></g></svg>`}
function render(){grid.replaceChildren();const list=catalog.shots.filter(s=>s.applicableBodies.includes(body.value)&&(!category.value||s.category===category.value)&&`${s.code} ${s.name}`.toLowerCase().includes(search.value.toLowerCase()));document.querySelector('#count').textContent=`${list.length} photographic guides · ${body.options[body.selectedIndex].textContent}`;list.forEach(s=>{const r=s.references[body.value],card=document.createElement('article');card.innerHTML=`<button aria-label="Enlarge ${s.name}">${svg(s)}</button><div class="info"><h2>${s.name}</h2><div class="code">${s.code}</div><small>${s.instruction}</small><small>${r.type} · <span class="complete">${r.status}</span><br>${r.asset} · crop ${r.rect.join(', ')}${r.mirror?' · mirrored':''}<br>Panel: ${s.panelState}${s.nominalAzimuthDegrees===null?'':` · nominal angle ${s.nominalAzimuthDegrees}°`}</small></div>`;card.querySelector('button').onclick=()=>{document.querySelector('#large').innerHTML=svg(s);document.querySelector('#detail').showModal()};grid.append(card)})}
body.onchange=category.onchange=search.oninput=render;document.querySelector('#close').onclick=()=>document.querySelector('#detail').close();render();</script></html>'''
(out/'Smart-Capture-V3-Reference-Catalog.html').write_text(page.replace('CATALOG',json.dumps(catalog)),encoding='utf-8')
print('Created photographic catalog HTML, 13 unchanged source images and machine-readable manifest in outputs/')
